INSERT INTO feature VALUES('soundness-exemplars','workflow','Historic soundness holes refuted as exemplars','executable-specifications','partial','notable',NULL,'A soundness issue of another checker, named in plain text, is re-staged as a pair of corpus sources: the hole''s shape refused in `pathological/soundness/` with the refusal named, and the sound program kept in `model/soundness/`; each pair folds its lesson into the plan or issue it changes.','surface-corpus','corpus/pathological/soundness/rust-164250.gandr corpus/model/soundness/rust-164250.gandr',NULL,'#1492');
